'use strict';

// MODULES //

var tape = require( 'tape' );
var Complex64 = require( '@stdlib/complex-float32-ctor' );
var PINF = require( '@stdlib/constants-float32-pinf' );
var NINF = require( '@stdlib/constants-float32-ninf' );
var isNotEqual = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof isNotEqual, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function tests whether two complex numbers are not equal (finite)', function test( t ) {
	var z1;
	var z2;

	z1 = new Complex64( 5.0, 3.0 );
	t.strictEqual( isNotEqual( z1, z1 ), false, 'returns expected value' );

	z1 = new Complex64( 5.0, 3.0 );
	z2 = new Complex64( 5.0, 3.0 );
	t.strictEqual( isNotEqual( z1, z2 ), false, 'returns expected value' );

	z1 = new Complex64( -5.0, 3.0 );
	z2 = new Complex64( 5.0, 3.0 );
	t.strictEqual( isNotEqual( z1, z2 ), true, 'returns expected value' );

	z1 = new Complex64( 5.0, 3.0 );
	z2 = new Complex64( -5.0, 3.0 );
	t.strictEqual( isNotEqual( z1, z2 ), true, 'returns expected value' );

	z1 = new Complex64( 5.0, -3.0 );
	z2 = new Complex64( 5.0, 3.0 );
	t.strictEqual( isNotEqual( z1, z2 ), true, 'returns expected value' );

	z1 = new Complex64( 5.0, 3.0 );
	z2 = new Complex64( 5.0, -3.0 );
	t.strictEqual( isNotEqual( z1, z2 ), true, 'returns expected value' );

	t.end();
});

tape( 'the function tests whether two complex numbers are not equal (infinite)', function test( t ) {
	var z1;
	var z2;

	z1 = new Complex64( PINF, NINF );
	t.strictEqual( isNotEqual( z1, z1 ), false, 'returns expected value' );

	z1 = new Complex64( PINF, NINF );
	z2 = new Complex64( PINF, NINF );
	t.strictEqual( isNotEqual( z1, z2 ), false, 'returns expected value' );

	z1 = new Complex64( NINF, 3.0 );
	z2 = new Complex64( PINF, 3.0 );
	t.strictEqual( isNotEqual( z1, z2 ), true, 'returns expected value' );

	z1 = new Complex64( PINF, 3.0 );
	z2 = new Complex64( NINF, 3.0 );
	t.strictEqual( isNotEqual( z1, z2 ), true, 'returns expected value' );

	z1 = new Complex64( PINF, -3.0 );
	z2 = new Complex64( PINF, 3.0 );
	t.strictEqual( isNotEqual( z1, z2 ), true, 'returns expected value' );

