'use strict';

// MODULES //

var bench = require( '@stdlib/bench-harness' );
var Complex64 = require( '@stdlib/complex-float32-ctor' );
var randu = require( '@stdlib/random-base-randu' );
var isBoolean = require( '@stdlib/assert-is-boolean' ).isPrimitive;
var pkg = require( './../package.json' ).name;
var isNotEqual = require( './../lib' );


// MAIN //

bench( pkg, function benchmark( b ) {
	var z1;
	var z2;
	var v;
	var i;

	z1 = [
		new Complex64( randu(), randu() ),
		new Complex64( randu(), randu() )
	];
	z2 = [
		new Complex64( randu(), randu() ),
		new Complex64( randu(), randu() ),
		z1[ 0 ],
		z1[ 1 ]
	];

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		v = isNotEqual( z1[ i%z1.length ], z2[ i%z2.length ] );
		if ( typeof v !== 'boolean' ) {
			b.fail( 'should return a boolean' );
		}
	}
	b.toc();
	if ( !isBoolean( v ) ) {
		b.fail( 'should return a boolean' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});","lineStart":1,"lineEnd":63,"totalLines":63,"truncated":false}},"title":"repos/pc-lib-3456/complex-float32-base-assert-is-not-equal/benchmark/benchmark.js","time":{"start":1783262669855,"end":1783262669858}},"id":"prt_f32bceaee0016Bir1Ca4nGwePP","sessionID":"ses_0cd439a91ffebExkHb8J1hz2uE","messageID":"msg_f32bcdfc7001QNDyxZrdHG6kMw"}}

